class ImageFrameGenerator : public ThreadSafeRefCounted<ImageFrameGenerator> {
public:
  ImageFrameGenerator() : full_size_(0, 0), color_behavior_(kDefaultColorBehavior), decoding_success_(false), alpha_present_(false) {
    MutexInit();
  }

  virtual ~ImageFrameGenerator() {
    MutexDestroy();
  }

  void SetFullSize(gfx::Size size) {
    MutexLock lock(&mutex_);
    full_size_ = size;
  }

  gfx::Size GetFullSize() const {
    MutexLock lock(&mutex_);
    return full_size_;
  }

  void SetColorBehavior(ColorBehavior behavior) {
    MutexLock lock(&mutex_);
    color_behavior_ = behavior;
  }

  ColorBehavior GetColorBehavior() const {
    MutexLock lock(&mutex_);
    return color_behavior_;
  }

  void SetSupportedSizes(const std::vector<gfx::Size>& sizes) {
    MutexLock lock(&mutex_);
    supported_sizes_ = sizes;
  }

  const std::vector<gfx::Size>& GetSupportedSizes() const {
    MutexLock lock(&mutex_);
    return supported_sizes_;
  }

  void SetDecodingSuccess(bool success) {
    MutexLock lock(&mutex_);
    decoding_success_ = success;
  }

  bool GetDecodingSuccess() const {
    MutexLock lock(&mutex_);
    return decoding_success_;
  }

  void SetAlphaPresent(bool present) {
    MutexLock lock(&mutex_);
    alpha_present_ = present;
  }

  bool GetAlphaPresent() const {
    MutexLock lock(&mutex_);
    return alpha_present_;
  }

  class ClientMutexLocker {
  public:
    ClientMutexLocker(ImageFrameGenerator* generator) : generator_(generator) {
      generator_->AcquireClientMutex();
    }

    ~ClientMutexLocker() {
      generator_->ReleaseClientMutex();
    }

  private:
    ImageFrameGenerator* generator_;
  };

private:
  void MutexInit() {
    mutex_.Init();
  }

  void MutexDestroy() {
    mutex_.Destroy();
  }

  void AcquireClientMutex() {
    ClientMutexMap::iterator it = client_mutex_map_.find(this);
    if (it != client_mutex_map_.end()) {
      it->second.Acquire();
    } else {
      Mutex new_mutex;
      new_mutex.Init();
      ClientMutexPair pair = std::make_pair(this, new_mutex);
      client_mutex_map_.insert(pair);
      new_mutex.Acquire();
    }
  }

  void ReleaseClientMutex() {
    ClientMutexMap::iterator it = client_mutex_map_.find(this);
    if (it != client_mutex_map_.end()) {
      it->second.Release();
    }
  }

  DISALLOW_COPY_AND_ASSIGN(ImageFrameGenerator);

  struct ClientMutexPair {
    ImageFrameGenerator* client;
    Mutex mutex;
  };

  typedef std::unordered_map<ImageFrameGenerator*, Mutex> ClientMutexMap;

  gfx::Size full_size_;
  ColorBehavior color_behavior_;
  std::vector<gfx::Size> supported_sizes_;
  bool decoding_success_;
  bool alpha_present_;
  Mutex mutex_;
  ClientMutexMap client_mutex_map_;
};

