// Define a ThreadSafeRefCounted-like structure for C
typedef struct ThreadSafeRefCounted {
    int ref_count;
    pthread_mutex_t mutex;
} ThreadSafeRefCounted;

// ImageFrameGenerator structure definition
typedef struct ImageFrameGenerator {
    ThreadSafeRefCounted base;
    int full_width;
    int full_height;
    bool has_alpha;
    int color_behavior;
    int supported_sizes;
    pthread_mutex_t state_mutex;
    Image* yuv_components[3];
    bool decoding_success;
    std::unordered_map<Client*, pthread_mutex_t> client_mutexes;
} ImageFrameGenerator;

// ClientMutexLocker structure definition
typedef struct ClientMutexLocker {
    ImageFrameGenerator* generator;
    Client* client;
    pthread_mutex_t* client_mutex;
} ClientMutexLocker;

// Function to add a reference to the object
void AddRef(ThreadSafeRefCounted* obj) {
    pthread_mutex_lock(&obj->mutex);
    obj->ref_count++;
    pthread_mutex_unlock(&obj->mutex);
}

// Function to release a reference to the object
void ReleaseRef(ThreadSafeRefCounted* obj) {
    pthread_mutex_lock(&obj->mutex);
    obj->ref_count--;
    if (obj->ref_count == 0) {
        pthread_mutex_unlock(&obj->mutex);
        free(obj);
        return;
    }
    pthread_mutex_unlock(&obj->mutex);
}

// Function to create an ImageFrameGenerator instance
ImageFrameGenerator* ImageFrameGeneratorCreate(int width, int height, int color_behavior, int supported_sizes) {
    ImageFrameGenerator* generator = (ImageFrameGenerator*)malloc(sizeof(ImageFrameGenerator));
    generator->base.ref_count = 1;
    pthread_mutex_init(&generator->base.mutex, NULL);
    generator->full_width = width;
    generator->full_height = height;
    generator->has_alpha = false;
    generator->color_behavior = color_behavior;
    generator->supported_sizes = supported_sizes;
    pthread_mutex_init(&generator->state_mutex, NULL);
    generator->decoding_success = false;
    return generator;
}

